CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `ams_result_details`  AS SELECT `u`.`user_id` AS `user_id`, `u`.`reg_no` AS `reg_no`, `u`.`batch_id` AS `batch_id`, `u`.`is_repeat` AS `is_repeat`, `c`.`course_code` AS `course_code`, `c`.`course_name` AS `course_name`, `c`.`credit` AS `credit`, `ce`.`quiz1_marks` AS `quiz1_marks`, `ce`.`quiz2_marks` AS `quiz2_marks`, `ce`.`quiz3_marks` AS `quiz3_marks`, `ce`.`total_quiz_marks` AS `total_quiz_marks`, `ce`.`quiz_marks` AS `quiz_marks`, `ce`.`assignment1_marks` AS `assignment1_marks`, `ce`.`assignment2_marks` AS `assignment2_marks`, `ce`.`mid_exam_marks` AS `mid_exam_marks`, `ce`.`total_CA_marks` AS `total_CA_marks`, `ce`.`CA_status` AS `CA_status`, `ce`.`eligibility` AS `eligibility`, `a`.`total_sessions` AS `total_sessions`, `a`.`present_sessions` AS `present_sessions`, round(100.0 * `a`.`present_sessions` / nullif(`a`.`total_sessions`,0),2) AS `attendance_percent`, `m`.`end_exam_marks` AS `end_exam_marks`, `m`.`total_marks` AS `total_marks`, `m`.`grade` AS `grade`, `m`.`grade_point` AS `grade_point` FROM (((((`enrollment` `e` join `undergraduate` `u` on(`u`.`reg_no` = `e`.`reg_no`)) join `course` `c` on(`c`.`course_id` = `e`.`course_id`)) join `ca_evaluation` `ce` on(`ce`.`enrollment_id` = `e`.`enrollment_id`)) join `mark` `m` on(`m`.`enrollment_id` = `e`.`enrollment_id`)) left join (select `attendance`.`enrollment_id` AS `enrollment_id`,count(0) AS `total_sessions`,sum(case when `attendance`.`status` = 'Present' then 1 else 0 end) AS `present_sessions` from `attendance` group by `attendance`.`enrollment_id`) `a` on(`a`.`enrollment_id` = `e`.`enrollment_id`)) ;

